package com.zamcan.codelab;

public final class Curriculum {
    private Curriculum() {}
    private static Lesson c(String title, String text, String body, String challenge, String q, String a, String b, String feedback) {
        return new Lesson(title, text, "#include <stdio.h>\n\nint main(void) {\n"+body+"\n    return 0;\n}\n", challenge, q, new String[]{a,b}, 0, feedback);
    }
    private static Lesson cpp(String title, String text, String body, String challenge, String q, String a, String b, String feedback) {
        return new Lesson(title, text, "#include <iostream>\n#include <string>\n#include <vector>\n#include <algorithm>\n\nint main() {\n"+body+"\n    return 0;\n}\n", challenge, q, new String[]{a,b}, 0, feedback);
    }
    public static Lesson[] lessons(boolean cpp) { return cpp ? CPP : C; }
    public static final Lesson[] C = {
        c("Meet C", "Dennis Ritchie developed C at Bell Labs in the early 1970s. It gives programs direct control over memory and is used in operating systems and embedded devices. A compiler translates source into machine code. Compilation and execution are separate steps.\n\n#include declares library interfaces; stdio.h supplies printf. main is the entry point. Braces group statements, a semicolon ends a statement, and return 0 reports successful termination. Indentation helps readers but does not replace braces.", "    printf(\"Hello, CodeLab!\\n\");", "Change the greeting and print a second line. Explain each punctuation mark.", "What does return 0 from main communicate?", "Successful termination", "Print the number zero", "Return values communicate status to the caller; printf produces text."),
        c("Values & types", "A variable names a typed storage location. int stores whole numbers, double floating-point approximations, and char a character. Initialize values before reading them. %d formats an int; %.2f displays two decimal places of a double. Floating point is approximate, so it is unsuitable for exact money accounting without an explicit policy.", "    int lessons = 10;\n    double hours = 2.5;\n    printf(\"%d lessons, %.2f hours\\n\", lessons, hours);", "Store a rectangle's width and height, then print its area.", "Which type represents fractional measurements?", "double", "int", "double can represent fractional approximations; int division discards a fractional part."),
        c("Input & arithmetic", "scanf reads formatted input and returns the number of successful conversions. & supplies the address where a value is stored. Always check the conversion count before using that value. The operators +, -, *, / and % perform arithmetic; % is integer remainder. Integer division truncates toward zero. Guard division by zero.", "    int count = 0;\n    printf(\"Enter a count: \");\n    if (scanf(\"%d\", &count) != 1) {\n        puts(\"Invalid input\");\n        return 1;\n    }\n    printf(\"Double: %d\\n\", count * 2);", "Read two small integers. Reject invalid input and a zero divisor before dividing. Consider overflow for large input.", "What is 7 / 2 with integer operands?", "3", "3.5", "Both operands are integers, so the fractional part is discarded."),
        c("Decisions", "if executes a block when its condition is nonzero. else handles the alternative. == compares; = assigns. Combine conditions with && (and) and || (or). Short-circuit evaluation can protect a later division or pointer access. Use braces even around short branches to make changes safer.", "    int score = 72;\n    if (score >= 50) {\n        puts(\"Pass\");\n    } else {\n        puts(\"Keep practicing\");\n    }", "Classify a score as invalid, pass, or retry. Test -1, 0, 49, 50, and 100.", "Which operator tests equality?", "==", "=", "A single equals sign changes a variable; two compare values."),
        c("Loops & tracing", "for groups initialization, a condition, and an update. The condition is checked before each iteration. while is useful when the number of repetitions is unknown. Trace the variables on paper to detect off-by-one errors. Every loop should make progress toward its exit condition.", "    int total = 0;\n    for (int i = 1; i <= 5; ++i) {\n        total += i;\n    }\n    printf(\"Sum: %d\\n\", total);", "Compute the sum from 1 to 10. Write a trace table containing i and total after every iteration.", "How many times does i = 0; i < 3; ++i run?", "3", "4", "The body runs for i equal to 0, 1, and 2."),
        new Lesson("Functions", "A function packages a named operation. Its parameter types and return type form a contract. C passes arguments by value: changing a parameter does not change the original variable. Declare functions before calling them. Small pure functions are easier to test.\n\nThe example's square receives an integer and returns its product. Restrict inputs when the product might exceed the int range.", "#include <stdio.h>\n\nint square(int value) {\n    return value * value;\n}\n\nint main(void) {\n    printf(\"%d\\n\", square(6));\n    return 0;\n}\n", "Write a maximum(a, b) function. Test equal, negative, and positive inputs.", "Are ordinary C arguments passed by value?", new String[]{"Yes", "No, always by reference"}, 0, "Each parameter receives a value. A pointer can be passed to access the caller's object."),
        c("Arrays & strings", "An array stores a fixed number of elements of one type. Indexing begins at zero, so an array of length 3 has valid indices 0 through 2. C does not automatically check bounds. A C string is a char array terminated by a zero byte, written \\0. Reserve space for that terminator; prefer bounded input such as fgets.", "    int marks[] = {70, 80, 90};\n    char name[32] = \"Ada\";\n    printf(\"%s: %d\\n\", name, marks[0]);", "Calculate the average of three marks. Explain why marks[3] is invalid.", "What is the last valid index of a 5-element array?", "4", "5", "Zero-based indices run from 0 through length minus 1."),
        c("Pointers & lifetime", "A pointer stores an address. & obtains an object's address; * dereferences a valid pointer. A null, uninitialized, or dangling pointer must not be dereferenced. Local variables stop existing when their scope ends; do not return their addresses. Dynamically allocated storage must be checked and eventually freed exactly once.", "    int value = 10;\n    int *pointer = &value;\n    *pointer = 20;\n    printf(\"%d\\n\", value);", "Create two integers and update each through a pointer. Describe when each pointer remains valid.", "What is printed in the example?", "20", "10", "pointer refers to value, so assigning through *pointer changes value."),
        c("Records & files", "struct groups related fields. Files persist data beyond one execution. fopen may fail; check its return before using the stream. Check write and close errors, and never assume external data is valid. A text format is easy to inspect but requires explicit delimiters and validation. Do not persist plaintext passwords.", "    struct Student { int id; double score; };\n    struct Student student = {1, 82.5};\n    FILE *file = fopen(\"results.txt\", \"w\");\n    if (file == NULL) { return 1; }\n    int written = fprintf(file, \"%d,%.1f\\n\", student.id, student.score);\n    int closed = fclose(file);\n    if (written < 0 || closed != 0) { return 1; }", "Explain why opening with w replaces old contents. Design validation rules for a student record.", "What must you check after fopen?", "Whether it returned NULL", "Whether the filename is uppercase", "NULL means opening failed; using that stream would be invalid."),
        c("Design & debugging", "Start with inputs, outputs, and invariants. Break a problem into small functions, then test normal cases, boundaries, and failures. Compiler diagnostics reveal syntax and type problems; a successful build does not prove correctness. Enable warnings and use sanitizers in a supported development environment.\n\nC++ can call a C API using extern \"C\" around declarations in C++ code. This requests C language linkage; it does not translate arbitrary C++ classes into C.", "    int values[] = {4, 1, 9};\n    int largest = values[0];\n    for (int i = 1; i < 3; ++i) {\n        if (values[i] > largest) largest = values[i];\n    }\n    printf(\"%d\\n\", largest);", "Move the maximum search into a function. Define how an empty input is handled before writing it.", "Does successful compilation prove correct behavior?", "No; behavior needs testing", "Yes", "Compilation checks language constraints, not whether the program meets its specification.")
    };
    public static final Lesson[] CPP = {
        cpp("Meet C++", "Bjarne Stroustrup developed C++ from work on C with Classes beginning in 1979. C++ supports procedural, object-oriented, and generic programming. It is not merely C with a different print function: its type system, object lifetime rules, and standard library enable different designs. Some valid C code is invalid C++.\n\n#include provides declarations. std:: names the standard namespace. << inserts a value into an output stream; main returns an exit status.", "    std::cout << \"Hello, C++!\\n\";", "Print your name and a learning goal on separate lines.", "What does std::cout represent?", "The standard output stream", "A compiler command", "Stream insertion sends formatted values to standard output."),
        cpp("Types & initialization", "Prefer initializing objects when declaring them. Brace initialization rejects many narrowing conversions. const communicates a value that must not change. auto deduces a type from an initializer; it does not make that type dynamic. Use integer minor units for a fictional money exercise and validate arithmetic limits.", "    const int days{7};\n    double hours{1.5};\n    auto total = days * hours;\n    std::cout << total << '\\n';", "Calculate weekly study time using a const number of days.", "Can a const int be reassigned?", "No", "Yes", "const prevents reassignment after initialization."),
        cpp("Streams & validation", "std::cin extracts formatted values. Check the stream state before using input. std::getline reads an entire line including spaces. Mixing extraction and getline requires handling the remaining newline. Failed extraction leaves the stream in an error state until cleared; do not create an endless retry loop.", "    int age{};\n    if (!(std::cin >> age) || age < 0 || age > 130) {\n        std::cerr << \"Invalid age\\n\";\n        return 1;\n    }\n    std::cout << age << '\\n';", "Read a temperature and validate a documented range. Try non-numeric input.", "Where should diagnostics usually go?", "std::cerr", "A variable named error", "std::cerr is the standard diagnostic stream."),
        cpp("Branches & loops", "C++ uses if, else, switch, for, and while for control flow. A range-based for visits each element of a collection without a manual index. Use a conventional loop when you need an index or special stepping. Keep conditions simple and check termination.", "    for (int value : {2, 4, 6}) {\n        if (value > 3) std::cout << value << '\\n';\n    }", "Print only even numbers from 1 through 20 and trace the condition.", "Which values does this example print?", "4 and 6", "2, 4, and 6", "The branch filters out values that are not greater than 3."),
        new Lesson("Functions & references", "A reference aliases an existing object. Passing by reference allows a function to change the caller's object; passing by const reference avoids a copy while preventing changes through that reference. References must not outlive their objects. Prefer returning values when ownership should be clear.", "#include <iostream>\n\nvoid increment(int& value) {\n    ++value;\n}\n\nint main() {\n    int count{2};\n    increment(count);\n    std::cout << count << '\\n';\n}\n", "Write a function that reads a string by const reference and returns its length.", "What does int& parameter mean?", new String[]{"A reference to an integer", "A new independent integer"}, 0, "A reference parameter aliases the caller's object."),
        cpp("Strings & vectors", "std::string owns a sequence of characters, and std::vector owns a resizable contiguous collection. Their destructors release resources automatically. size reports the number of elements; at checks bounds and throws on an invalid index, whereas operator[] requires a valid index. Adding elements can invalidate references into a vector.", "    std::vector<int> scores{70, 80};\n    scores.push_back(90);\n    std::string learner = \"Ada\";\n    std::cout << learner << \": \" << scores.at(2) << '\\n';", "Compute an average from a vector. Handle an empty vector before dividing.", "Which access operation checks bounds?", "at(index)", "operator[]", "at throws std::out_of_range when the index is invalid."),
        new Lesson("Classes & invariants", "A class groups state and operations. private hides representation; public exposes a usable interface. A constructor establishes valid initial state. Operations should preserve an invariant, a condition that remains true after every public call. A class is useful when it protects a meaningful rule, not just because a program uses C++.", "#include <iostream>\n\nclass Counter {\n    int value{0};\npublic:\n    void increment() { if (value < 100) ++value; }\n    int get() const { return value; }\n};\n\nint main() {\n    Counter counter;\n    counter.increment();\n    std::cout << counter.get() << '\\n';\n}\n", "Design a fictional account with nonnegative integer balance. Reject withdrawals larger than the balance.", "What is an invariant?", new String[]{"A rule valid state must preserve", "A variable that changes type"}, 0, "Public operations must preserve the class's state rules."),
        new Lesson("Lifetime & RAII", "Resource acquisition is initialization (RAII) binds a resource to an object's lifetime. Standard containers, file streams, and smart pointers release owned resources when destroyed, including during exception unwinding. Prefer these owners to manual new/delete. A unique_ptr has one owner and transfers ownership by moving, not copying.", "#include <iostream>\n#include <memory>\n\nint main() {\n    auto value = std::make_unique<int>(42);\n    std::cout << *value << '\\n';\n}\n", "Explain who owns the integer and when it is released. Compare this with a raw pointer.", "When is the owned integer released here?", new String[]{"When its unique_ptr is destroyed", "Only after a manual delete"}, 0, "The owning smart pointer releases its resource automatically."),
        cpp("Algorithms & generic code", "Standard algorithms express operations on ranges. std::sort reorders a range; std::find searches it. begin and end describe a half-open range: the end iterator is not an element. Templates allow algorithms to work with multiple types while retaining compile-time checking. Select algorithms based on correctness and complexity.", "    std::vector<int> values{9, 2, 5};\n    std::sort(values.begin(), values.end());\n    for (int value : values) std::cout << value << ' ';\n    std::cout << '\\n';", "Sort scores, then find a target score. Handle the not-found iterator correctly.", "Can you dereference end()?", "No", "Yes, it is the last item", "end marks the position past the last element."),
        cpp("Robust program design", "Separate input, domain rules, storage, and presentation. Check file operations and parse failures. Test boundaries and invalid operations, not only happy paths. Exceptions can communicate failures, but a catch block must implement a useful recovery or reporting policy.\n\nFor C interoperability, wrap C function declarations in extern \"C\" when included by C++. Use C-compatible data at the boundary and define ownership. Do not allow C++ exceptions to cross a C ABI boundary.", "    std::vector<int> values{3, 5, 7};\n    int sum{};\n    for (int value : values) sum += value;\n    if (!values.empty()) {\n        std::cout << static_cast<double>(sum) / values.size() << '\\n';\n    }", "Design a grades program with separate validation and averaging functions. Specify tests for empty, invalid, and boundary inputs.", "What does extern \"C\" specify in C++?", "C language linkage", "Automatic conversion of classes to C", "It controls language linkage; it does not make C++ classes compatible with C.")
    };
}
